insert into public.properties (id, ref, slug, title, category, segment, type, community_slug, building, price, bedrooms, bathrooms, area_sqft, plot_sqft, furnishing, summary, description, amenities, images, floor_plan, lat, lng, location_precision, agent_id, featured, published, status, verification, off_plan, rental_yield, is_demo, created_at, updated_at) values ('prop_nxrd1001', 'NXR-D-1001', 'two-bedroom-residence-with-burj-khalifa-views-nxr-d-1001', 'Two-bedroom residence with Burj Khalifa views', 'sale', 'residential', 'apartment', 'downtown-dubai', null, 3650000, 2, 3, 1420, null, 'unfurnished', 'A corner two-bedroom on a high floor with floor-to-ceiling glazing towards Burj Khalifa and the Fountain.', array['This corner residence is arranged around an open living and dining room with full-height glazing on two sides. Both bedrooms have en-suite bathrooms, with a guest powder room off the entrance hall.', 'The kitchen is fitted with integrated appliances and stone worktops. Residents have access to a pool deck, gym and 24-hour concierge, and the Boulevard is a short walk from the lobby.']::text[], array['Burj Khalifa view', 'Swimming pool', 'Gym', '24-hour concierge', 'Covered parking', 'Built-in wardrobes']::text[], '[{"src":"https://images.unsplash.com/photo-1757924461488-ef9ad0670978","alt":"Living room with large windows and lounge seating","credit":"Aalo Lens","kind":"photo"},{"src":"https://images.unsplash.com/photo-1616594039964-ae9021a400a0","alt":"Bedroom with an upholstered bed and city view","credit":"Spacejoy","kind":"photo"},{"src":"https://images.unsplash.com/photo-1683629357963-adf2b1fa9ad9","alt":"Kitchen with marble worktops and white cabinetry","credit":"Brian Zajac","kind":"photo"},{"src":"https://images.unsplash.com/photo-1719474818095-2d75b8b57251","alt":"Bathroom with a large mirror and vanity","credit":"Nisha Vastu","kind":"photo"},{"src":"https://images.unsplash.com/photo-1739900292622-a7f860175aad","alt":"City lights seen from the top of a tower at night","credit":"Nejc Soklič","kind":"photo"}]'::jsonb, null, 25.195, 55.276, 'community', 'agent_aisha', true, true, 'available', null, null, null, true, '2026-10-06T09:00:00.000Z', '2026-10-06T09:00:00.000Z') on conflict (id) do nothing;
insert into public.properties (id, ref, slug, title, category, segment, type, community_slug, building, price, bedrooms, bathrooms, area_sqft, plot_sqft, furnishing, summary, description, amenities, images, floor_plan, lat, lng, location_precision, agent_id, featured, published, status, verification, off_plan, rental_yield, is_demo, created_at, updated_at) values ('prop_nxrd1002', 'NXR-D-1002', 'marina-facing-three-bedroom-apartment-nxr-d-1002', 'Marina-facing three-bedroom apartment', 'sale', 'residential', 'apartment', 'dubai-marina', null, 4150000, 3, 4, 2050, null, 'unfurnished', 'Wide marina views from a generous three-bedroom with a separate maid''s room and a long balcony.', array['Set on a mid-to-high floor, this three-bedroom apartment looks directly over the marina berths. The living room opens onto a long balcony that runs the width of the apartment.', 'The layout separates the bedrooms from the entertaining space, and includes a maid''s room with its own bathroom. Marina Walk, the tram and the beach are all within walking distance.']::text[], array['Marina view', 'Balcony', 'Maid''s room', 'Swimming pool', 'Gym', 'Two parking spaces']::text[], '[{"src":"https://images.unsplash.com/photo-1580674684081-7617fbf3d745","alt":"High-rise towers beside the water","credit":"Wael Hneini","kind":"photo"},{"src":"https://images.unsplash.com/photo-1568115286680-d203e08a8be6","alt":"Living area with full-height glazing","credit":"Moritz Bruder","kind":"photo"},{"src":"https://images.unsplash.com/photo-1505693416388-ac5ce068fe85","alt":"Bedroom with a tufted headboard","credit":"Quilia","kind":"photo"},{"src":"https://images.unsplash.com/photo-1686056040167-1e3dead46d9a","alt":"Large kitchen with a central island and bar stools","credit":"Brian Zajac","kind":"photo"}]'::jsonb, null, 25.08, 55.14, 'community', 'agent_aisha', true, true, 'available', null, null, null, true, '2026-10-03T09:00:00.000Z', '2026-10-03T09:00:00.000Z') on conflict (id) do nothing;
insert into public.properties (id, ref, slug, title, category, segment, type, community_slug, building, price, bedrooms, bathrooms, area_sqft, plot_sqft, furnishing, summary, description, amenities, images, floor_plan, lat, lng, location_precision, agent_id, featured, published, status, verification, off_plan, rental_yield, is_demo, created_at, updated_at) values ('prop_nxrd1003', 'NXR-D-1003', 'five-bedroom-beachfront-villa-on-the-fronds-nxr-d-1003', 'Five-bedroom beachfront villa on the fronds', 'sale', 'residential', 'villa', 'palm-jumeirah', null, 28500000, 5, 6, 7200, 9800, 'unfurnished', 'A contemporary villa with direct beach access, a private pool and views back towards the Marina skyline.', array['This villa sits on a frond plot with a private stretch of beach. The ground floor opens fully to the garden and pool terrace, with a formal living room, family room and a show kitchen backed by a separate service kitchen.', 'Five bedroom suites are arranged across the upper floors, with the principal suite taking a full wing including a dressing room and a sea-facing terrace.']::text[], array['Private beach', 'Private pool', 'Sea view', 'Service kitchen', 'Maid''s and driver''s rooms', 'Landscaped garden']::text[], '[{"src":"https://images.unsplash.com/photo-1543489822-c49534f3271f","alt":"Infinity pool overlooking the bay","credit":"big.tiny.belly","kind":"photo"},{"src":"https://images.unsplash.com/photo-1544984243-ec57ea16fe25","alt":"Pool beside a house at golden hour","credit":"Roberto Nickson","kind":"photo"},{"src":"https://images.unsplash.com/photo-1758448755952-42b404bc6f39","alt":"Living room with tailored furniture and decor","credit":"Aalo Lens","kind":"photo"},{"src":"https://images.unsplash.com/photo-1617098900591-3f90928e8c54","alt":"Bedroom with a crystal chandelier and dark bedside tables","credit":"Spacejoy","kind":"photo"},{"src":"https://images.unsplash.com/photo-1639405069836-f82aa6dcb900","alt":"Kitchen with stainless steel appliances and marble worktops","credit":"Lotus Design N Print","kind":"photo"}]'::jsonb, null, 25.112, 55.138, 'community', 'agent_elena', true, true, 'available', null, null, null, true, '2026-09-29T09:00:00.000Z', '2026-09-29T09:00:00.000Z') on conflict (id) do nothing;
